"use server";

// Generated by philote from page /horses/new. Do not edit.
import { redirect } from "next/navigation";

import { horses } from "@/lib/api";
import { type FormState, failed, int, text } from "@/lib/form";
import type { Breed } from "@/lib/types";

export async function submit(_state: FormState, data: FormData): Promise<FormState> {
    const result = await horses.create({
        name: text(data, "name"),
        breed: text<Breed>(data, "breed"),
        age: int(data, "age"),
        bio: text(data, "bio"),
    });
    if (!result.ok) {
        return failed(data, result.error, result.issues);
    }
    redirect(`/horses/${encodeURIComponent(result.value.id)}`);
}
